function updateTeacherProfileMatch(){const id=document.getElementById("entry-id").value.trim(),box=document.getElementById("teacher-profile-match"),p=getProfile(id,activeTeacherSchool);if(!id){box.hidden=true;box.innerHTML="";return;}if(p){box.innerHTML=`<div class="match-content"><img class="student-photo" src="${p.photo}" alt="Registered student photo"><div><strong>${escapeHTML(p.name)}</strong><span>School-admin registered profile · ${escapeHTML(p.id)} · DOB: ${escapeHTML(p.dob||"Not recorded")}</span></div><span class="match-status">Photo matched</span></div>`;box.hidden=false;const name=document.getElementById("entry-name");if(!name.value.trim()||name.dataset.profileId!==p.id){name.value=p.name;name.dataset.profileId=p.id;}}else{box.innerHTML=`<div class="match-content"><div class="student-photo photo-initials">?</div><div><strong>No registered profile found</strong><span>Ask the school administrator to add this Student ID and photo.</span></div></div>`;box.hidden=false;}}document.getElementById("entry-id").addEventListener("input",updateTeacherProfileMatch);
