document.getElementById("restore-file").addEventListener("change",async e=>{const file=e.target.files?.[0];e.target.value="";if(!file||!teacherSignedIn)return;try{const data=JSON.parse(await file.text());if(data.format!=="school-results-portal-backup"||!Array.isArray(data.records)||!Array.isArray(data.profiles))throw new Error("This is not a valid portal backup.");if(!confirm(`Restore ${data.records.length} result record(s) and ${data.profiles.length} student profile(s) for ${activeTeacherSchool}? Existing records with matching student/year/semester and profiles with matching IDs will be replaced.`))return;const importedRecords=data.records.filter(r=>schoolMatches(r,activeTeacherSchool)&&r.id&&r.name&&r.scores&&typeof r.scores==="object");const importedProfiles=data.profiles.filter(p=>schoolMatches(p,activeTeacherSchool)&&p.id&&p.name);for(const r of importedRecords){records=records.filter(old=>!(schoolMatches(old,activeTeacherSchool)&&old.id.toUpperCase()===r.id.toUpperCase()&&(old.academicYear||"JHS 1")===(r.academicYear||"JHS 1")&&(old.semester||"First Term")===(r.semester||"First Term")));records.push(r);}for(const p of importedProfiles){profiles=profiles.filter(old=>!(schoolMatches(old,activeTeacherSchool)&&old.id.toUpperCase()===p.id.toUpperCase()));profiles.push(p);}if(typeof data.schoolEmblem==="string"&&data.schoolEmblem.startsWith("data:image/")){emblems[schoolKey(activeTeacherSchool)]=data.schoolEmblem;saveEmblems();}saveRecords();saveProfiles();renderStudentTable();renderDirectory();showMessage(document.getElementById("entry-message"),`Backup restored: ${importedRecords.length} result record(s), ${importedProfiles.length} student profile(s)${data.schoolEmblem?", and school emblem":""}.`,true);}catch(err){alert("Could not restore this backup. Please choose a valid JSON backup exported by this portal.");}});
