function editRecord(id,year="JHS 1",semester="First Term",schoolYear="2026/2027"){const r=records.find(x=>x.id===id&&schoolMatches(x,activeTeacherSchool)&&(x.academicYear||"JHS 1")===year&&(x.schoolYear||"2026/2027")===schoolYear&&(x.semester||"First Term")===semester);if(!r)return;document.getElementById("entry-name").value=r.name;document.getElementById("entry-id").value=r.id;document.getElementById("entry-pin").value=r.pin;document.getElementById("entry-exam").value=r.exam;document.getElementById("entry-year").value=r.academicYear||"JHS 1";document.getElementById("entry-academic-year").value=r.schoolYear||"2026/2027";document.getElementById("entry-semester").value=r.semester||"First Term";document.getElementById("entry-pass-mark").value=r.passMark??50;subjects.forEach((s,i)=>document.getElementById("score-"+i).value=r.scores[s]??"");document.getElementById("publish-result").checked=r.published;document.getElementById("entry-id").dataset.originalId=r.id;document.getElementById("entry-id").dataset.originalYear=r.academicYear||"JHS 1";document.getElementById("entry-id").dataset.originalSchoolYear=r.schoolYear||"2026/2027";document.getElementById("entry-id").dataset.originalSemester=r.semester||"Second Term";updateTeacherProfileMatch();document.getElementById("entry-name").focus();}
