document.getElementById("entry-form").addEventListener("submit",e=>{e.preventDefault();if(!teacherSignedIn)return;const msg=document.getElementById("entry-message"),originalId=document.getElementById("entry-id").dataset.originalId,originalSchoolYear=document.getElementById("entry-id").dataset.originalSchoolYear,originalYear=document.getElementById("entry-id").dataset.originalYear,originalSemester=document.getElementById("entry-id").dataset.originalSemester,id=document.getElementById("entry-id").value.trim().toUpperCase(),profile=getProfile(id,activeTeacherSchool),scores={};let invalid=false,count=0;subjects.forEach((s,i)=>{const raw=document.getElementById("score-"+i).value.trim();if(raw===""){scores[s]=null;return;}const n=Number(raw);if(!Number.isFinite(n)||n<0||n>100)invalid=true;else{scores[s]=n;count++;}});if(invalid){showMessage(msg,"Each entered score must be a number from 0 to 100.");return;}if(!count){showMessage(msg,"Enter at least one subject score before saving or publishing.");return;}const academicYear=document.getElementById("entry-year").value,schoolYear=document.getElementById("entry-academic-year").value,semester=document.getElementById("entry-semester").value,passMark=Number(document.getElementById("entry-pass-mark").value);if(!Number.isFinite(passMark)||passMark<0||passMark>100){showMessage(msg,"Pass mark must be between 0 and 100.");return;}if(records.some(r=>schoolMatches(r,activeTeacherSchool)&&r.id.toUpperCase()===id&&r.id!==originalId&&(r.academicYear||"JHS 1")===academicYear&&(r.schoolYear||"2026/2027")===schoolYear&&(r.semester||"First Term")===semester)){showMessage(msg,"A result already exists for this student in that year and semester. Use Edit on that period to update it.");return;}if(profile&&document.getElementById("entry-name").value.trim().toLowerCase()!==profile.name.toLowerCase()){showMessage(msg,"The name does not match the school-admin profile for this Student ID. Use the registered name.");return;}const name=profile?profile.name:document.getElementById("entry-name").value.trim();if(!name||!document.getElementById("entry-pin").value.trim()){showMessage(msg,"Please enter the student's name and PIN.");return;}const record={school:activeTeacherSchool,name,id,pin:document.getElementById("entry-pin").value.trim(),exam:document.getElementById("entry-exam").value.trim(),academicYear,schoolYear,semester,published:document.getElementById("publish-result").checked,scores,passMark};records=records.filter(r=>!(schoolMatches(r,activeTeacherSchool)&&((r.id===originalId&&(r.academicYear||"JHS 1")===(originalYear||academicYear)&&(r.schoolYear||"2026/2027")===(originalSchoolYear||schoolYear)&&(r.semester||"Second Term")===(originalSemester||semester))||(r.id.toUpperCase()===id&&(r.academicYear||"JHS 1")===academicYear&&(r.schoolYear||"2026/2027")===schoolYear&&(r.semester||"Second Term")===semester))));records.push(record);saveRecords();delete document.getElementById("entry-id").dataset.originalId;delete document.getElementById("entry-id").dataset.originalYear;delete document.getElementById("entry-id").dataset.originalSchoolYear;delete document.getElementById("entry-id").dataset.originalSemester;renderStudentTable();showMessage(msg,record.published?`Result saved and published (${count} subject${count===1?"":"s"} entered).`:`Result saved as a draft (${count} subjects entered).`,true);document.getElementById("entry-form").reset();document.getElementById("entry-exam").value="End-of-Term Examination";document.getElementById("entry-year").value="JHS 1";document.getElementById("entry-academic-year").value="2026/2027";document.getElementById("entry-semester").value="First Term";document.getElementById("entry-pass-mark").value=50;document.getElementById("teacher-profile-match").hidden=true;});
