function renderEmblemSettings(){const emblem=getSchoolEmblem(activeAdminSchool),preview=document.getElementById("school-emblem-preview"),placeholder=document.getElementById("school-emblem-placeholder");pendingEmblem=emblem;if(emblem){preview.src=emblem;preview.hidden=false;placeholder.hidden=true;}else{preview.removeAttribute("src");preview.hidden=true;placeholder.hidden=false;}document.getElementById("remove-school-emblem").disabled=!emblem;}
document.getElementById("school-emblem-file").addEventListener("change",async e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith("image/")){showMessage(document.getElementById("emblem-message"),"Choose an image file for the school emblem.");return;}try{pendingEmblem=await compressImage(file,320,0.72);const preview=document.getElementById("school-emblem-preview");preview.src=pendingEmblem;preview.hidden=false;document.getElementById("school-emblem-placeholder").hidden=true;showMessage(document.getElementById("emblem-message"),"Emblem selected. Choose Save school emblem to apply it to results.",true);}catch{showMessage(document.getElementById("emblem-message"),"Could not read that image. Try another emblem image.");}});
