document.getElementById("profile-photo-file").addEventListener("change",async e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith("image/")){showMessage(document.getElementById("profile-message"),"Choose an image file.");return;}try{pendingPhoto=await compressImage(file);document.getElementById("profile-photo-preview").src=pendingPhoto;document.getElementById("profile-photo-preview").hidden=false;document.getElementById("profile-photo-placeholder").hidden=true;}catch{showMessage(document.getElementById("profile-message"),"Could not read that image. Try another photo.");}});
function compressImage(file,max=480,quality=0.78){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{const scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext("2d").drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL("image/jpeg",quality));};img.src=reader.result;};reader.readAsDataURL(file);});}
document.getElementById("profile-form").addEventListener("submit",e=>{e.preventDefault();if(!adminSignedIn)return;const msg=document.getElementById("profile-message"),name=document.getElementById("profile-name").value.trim(),id=document.getElementById("profile-id").value.trim().toUpperCase(),dob=document.getElementById("profile-dob").value,originalId=document.getElementById("profile-id").dataset.originalId,old=getProfile(originalId||id,activeAdminSchool);if(!name||!id||!dob){showMessage(msg,"Enter the student's full name, Student ID and date of birth.");return;}if(dob>new Date().toISOString().slice(0,10)){showMessage(msg,"Date of birth cannot be in the future.");return;}if(!pendingPhoto&&!old?.photo){showMessage(msg,"Please choose a student photo from your files.");return;}if(profiles.some(p=>schoolMatches(p,activeAdminSchool)&&p.id.toUpperCase()===id&&p.id!==originalId)){showMessage(msg,"That Student ID already has a profile. Use Edit profile.");return;}const profile={school:activeAdminSchool,name,id,dob,photo:pendingPhoto||old.photo};profiles=profiles.filter(p=>!(schoolMatches(p,activeAdminSchool)&&(p.id===originalId||p.id.toUpperCase()===id)));profiles.push(profile);saveProfiles();renderDirectory();showMessage(msg,`Student profile saved for ${name}. Teachers can now match this ID to the photo.`,true);clearProfileForm(false);});
function renderDirectory(){const box=document.getElementById("student-directory"),q=(document.getElementById("profile-search")?.value||"").trim().toLowerCase();document.getElementById("profile-count").textContent=`${profiles.filter(p=>schoolMatches(p,activeAdminSchool)).length} profile${profiles.filter(p=>schoolMatches(p,activeAdminSchool)).length===1?"":"s"}`;const statProfiles=document.getElementById("stat-profiles");if(statProfiles)statProfiles.textContent=profiles.filter(p=>schoolMatches(p,activeAdminSchool)).length;const schoolProfiles=profiles.filter(p=>schoolMatches(p,activeAdminSchool));const visible=schoolProfiles.filter(p=>[p.name,p.id,p.dob].some(v=>String(v||"").toLowerCase().includes(q)));box.innerHTML=visible.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<article class="directory-card"><img src="${p.photo}" alt="Student photo of ${escapeHTML(p.name)}"><div class="directory-info"><strong>${escapeHTML(p.name)}</strong><span>${escapeHTML(p.id)}</span><span>${escapeHTML(p.school||activeAdminSchool)}</span><span>DOB: ${escapeHTML(p.dob||"Not recorded")}</span></div><div class="directory-actions"><button type="button" class="secondary small" data-profile-edit="${escapeHTML(p.id)}">Edit</button><button type="button" class="secondary small" data-profile-delete="${escapeHTML(p.id)}">Delete</button></div></article>`).join("")||(q?"<p class='empty-directory'>No profiles match your search.</p>":"<p class='empty-directory'>No student profiles yet. Add the first student's details and photo above.</p>");box.querySelectorAll("[data-profile-edit]").forEach(b=>b.addEventListener("click",()=>editProfile(b.dataset.profileEdit)));box.querySelectorAll("[data-profile-delete]").forEach(b=>b.addEventListener("click",()=>deleteProfile(b.dataset.profileDelete)));}
function editProfile(id){const p=getProfile(id,activeAdminSchool);if(!p)return;document.getElementById("profile-name").value=p.name;document.getElementById("profile-id").value=p.id;document.getElementById("profile-dob").value=p.dob||"";document.getElementById("profile-id").dataset.originalId=p.id;pendingPhoto=p.photo;document.getElementById("profile-photo-preview").src=p.photo;document.getElementById("profile-photo-preview").hidden=false;document.getElementById("profile-photo-placeholder").hidden=true;document.getElementById("profile-photo-file").value="";}
