// Global search: public portal content for everyone, with school-scoped records only in authorized workspaces.
(function initGlobalSearch(){
  const input=document.getElementById("global-search-input");
  const form=document.getElementById("global-search-form");
  const panel=document.getElementById("global-search-results");
  if(!input||!form||!panel)return;
  const icons={Page:"⌂",Feature:"✦",Subject:"▤",School:"⌂",Student:"♙",Result:"✓",Help:"i"};
  function publicItems(){
    const items=[];
    const seen=new Set();
    // Index nearly all authored website text, including hidden portal sections,
    // form labels, placeholders, help text, navigation, buttons, and option names.
    const selector='h1,h2,h3,h4,h5,h6,p,label,button,a,li,summary,legend,th,td,dt,dd,option,[title],[aria-label],[placeholder],[alt],.eyebrow,.small-note,.notice,.card,.feature-card,.nav-link';
    document.querySelectorAll(selector).forEach(el=>{
      if(el.closest('.global-search-shell')||el.closest('footer')||el.matches('script,style,noscript'))return;
      const bits=[];
      const text=(el.innerText||el.textContent||'').replace(/\s+/g,' ').trim();
      if(text&&text.length>=2)bits.push(text);
      ['placeholder','title','aria-label','alt','name','value'].forEach(attr=>{
        const val=el.getAttribute(attr);
        if(val&&val.trim()&&!/password|token|secret/i.test(attr+' '+val))bits.push(val.trim());
      });
      if(el.tagName==='INPUT'||el.tagName==='SELECT'||el.tagName==='TEXTAREA'){
        const label=el.labels?Array.from(el.labels).map(x=>(x.innerText||x.textContent||'').trim()).join(' '):'';
        if(label)bits.push(label);
        if(el.options)Array.from(el.options).forEach(o=>{if(o.textContent.trim())bits.push(o.textContent.trim());});
      }
      const full=Array.from(new Set(bits)).join(' — ').replace(/\s+/g,' ').trim();
      if(full.length<2)return;
      const key=full.toLowerCase();
      if(seen.has(key))return;seen.add(key);
      const section=el.closest("[id^='view-']");
      let view=section?section.id.replace('view-',''):'check';
      if(el.matches('button[data-view],button[data-goto],a[data-view],a[data-goto]'))view=el.dataset.view||el.dataset.goto||view;
      const type=el.matches('h1,h2,h3,h4,h5,h6')?'Page':el.matches('input,select,textarea,label,option,legend')?'Form':el.matches('a,button')?'Action':el.matches('li,th,td,dt,dd')?'Content':el.matches('.notice,.small-note')?'Help':'Content';
      items.push({title:full.slice(0,110),description:full.slice(0,220),type,view,search:key});
    });
    // Include terms and features that may be represented by generated controls.
    ghanaSchools.forEach(name=>items.push({title:name,description:'Ghana Ghana school suggestion (JHS/basic or SHS). Select it or type any school name in the relevant portal form.',type:'School',view:'check',search:name.toLowerCase()}));
    subjects.forEach(name=>items.push({title:name,description:'Subject available in the teacher score-entry form and result slip.',type:'Subject',view:'teacher',search:name.toLowerCase()}));
    [
      ['Student date of birth','Registered by the school admin and shown on the result slip.','admin'],
      ['Student photo upload','Upload and manage student photos from the school admin directory.','admin'],
      ['Search results','Search result records by student name, Student ID, exam or status in the teacher workspace.','teacher'],
      ['Result PIN','Students need their school, Student ID and result PIN to check a published result.','check'],
      ['Publish results','Teachers can publish results after entering one or more subject scores.','teacher'],
      ['Save draft','Teachers can save an unpublished result as a draft.','teacher'],
      ['Print result','Students can print a published statement of results.','check'],
      ['Download CSV','Download a result or export school records as a CSV file.','teacher'],
      ['JHS and SHS subjects','Teachers can enter scores for JHS and SHS core and elective subjects; blank subjects remain blank.','teacher'],
      ['School selection','Select or type the school name to keep student profiles and results associated with that school.','check'],
      ['Student directory','The school admin can register names, IDs, dates of birth and photos.','admin'],
      ['Grade bands','Scores are converted to grades from A1 to F9.','about'],
      ['Global website search','Search page text, navigation, form fields, buttons, help text, school options, subjects, and authorised school records.','check']
    ].forEach(([title,description,view])=>items.push({title,description,type:'Feature',view,search:(title+' '+description).toLowerCase()}));
    return items;
  }
  const baseItems=publicItems();
  function searchItems(q){
    const found=[];
    const add=(item)=>{if(item.search.includes(q)||item.title.toLowerCase().includes(q)||item.description.toLowerCase().includes(q))found.push(item);};
    baseItems.forEach(add);
    // Student data is only included for the authenticated, school-scoped workspace.
    if(teacherSignedIn){
      records.filter(r=>schoolMatches(r,activeTeacherSchool)).forEach(r=>{
        const profile=getProfile(r.id,activeTeacherSchool);
        const searchable=[r.name,r.id,r.exam,r.school,r.academicYear||"JHS 1",r.schoolYear||"2026/2027",r.semester||"First Term",...subjects].join(" ").toLowerCase();
        if(searchable.includes(q))found.push({title:`${r.name} · ${r.id}`,description:`${r.school} — ${r.academicYear||"JHS 1"}, ${r.semester||"First Term"} — ${r.exam} — ${r.published?"Published":"Draft"}`,type:"Result",view:"teacher",search:searchable,privateKind:"record",id:r.id});
        if(profile&&`${profile.name} ${profile.id} ${profile.dob}`.toLowerCase().includes(q))found.push({title:`Student profile: ${profile.name}`,description:`${profile.school} — ID ${profile.id}`,type:"Student",view:"teacher",search:searchable,privateKind:"record",id:r.id});
      });
    }
    if(adminSignedIn){
      profiles.filter(p=>schoolMatches(p,activeAdminSchool)).forEach(p=>{
        const searchable=`${p.name} ${p.id} ${p.dob} ${p.school}`.toLowerCase();
        if(searchable.includes(q))found.push({title:`${p.name} · ${p.id}`,description:`Student profile in ${p.school}; date of birth ${p.dob||"not recorded"}.`,type:"Student",view:"admin",search:searchable,privateKind:"profile",id:p.id});
      });
    }
    const seen=new Set();
    return found.filter(item=>{const k=`${item.title}|${item.view}|${item.privateKind||""}`;if(seen.has(k))return false;seen.add(k);return true;}).slice(0,30);
  }
  function closeResults(){panel.hidden=true;input.setAttribute("aria-expanded","false");}
  function render(){
    const q=input.value.trim().toLowerCase();
    if(!q){closeResults();panel.innerHTML="";return;}
    const found=searchItems(q);
    panel.innerHTML=found.length?found.map((item,i)=>`<button type="button" class="global-search-result" data-search-index="${i}"><span class="global-search-result-icon" aria-hidden="true">${icons[item.type]||"⌕"}</span><span class="global-search-result-copy"><small>${escapeHTML(item.type)}</small><strong>${escapeHTML(item.title)}</strong><span>${escapeHTML(item.description)}</span></span></button>`).join(""):`<div class="global-search-empty">No matches found for “${escapeHTML(input.value.trim())}”. Try any word from a page, button, form field, instruction, subject or school name.</div>`;
    panel.hidden=false;input.setAttribute("aria-expanded","true");
    panel.querySelectorAll("[data-search-index]").forEach((button,i)=>button.addEventListener("click",()=>activate(found[i])));
  }
  function activate(item){
    closeResults();
    if(item.privateKind==="record"&&teacherSignedIn){showView("teacher");document.getElementById("record-search").value=item.id;renderStudentTable();document.getElementById("teacher-workspace").scrollIntoView({behavior:"smooth",block:"start"});return;}
    if(item.privateKind==="profile"&&adminSignedIn){showView("admin");document.getElementById("profile-search").value=item.id;renderDirectory();document.getElementById("admin-workspace").scrollIntoView({behavior:"smooth",block:"start"});return;}
    showView(item.view||"check");
    const target=document.getElementById("view-"+(item.view||"check"));
    if(target)target.scrollIntoView({behavior:"smooth",block:"start"});
  }
  input.addEventListener("input",render);
  form.addEventListener("submit",e=>{e.preventDefault();const q=input.value.trim().toLowerCase();if(!q){input.focus();return;}const found=searchItems(q);if(found[0])activate(found[0]);else render();});
  document.addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"){e.preventDefault();input.focus();input.select();}});
  document.addEventListener("click",e=>{if(!e.target.closest(".global-search-shell"))closeResults();});
})();
